import {ThemeProvider,useTheme,Palette} from './src/theme';
import React, { useEffect, useMemo, useRef, useState } from 'react';
import { View, Text, Pressable, ScrollView, TextInput, StyleSheet, useWindowDimensions, Platform, Linking, ActivityIndicator, KeyboardAvoidingView, Keyboard, StatusBar, BackHandler, Switch } from 'react-native';
import { SafeAreaView, SafeAreaProvider, useSafeAreaInsets } from 'react-native-safe-area-context';
import AsyncStorage from '@react-native-async-storage/async-storage';
import * as Location from 'expo-location';
import { Home, Users, MessageCircle, Clock, Settings, ArrowUpRight, ArrowRight, Plus, ChevronRight, ChevronLeft, ShieldCheck, Heart, FileText, Upload, Sparkles, Check, Dna, Leaf, MapPin, Sun, Send, Download, LockKeyhole, Stethoscope, Phone, X, Bell, Globe, LogOut, Pencil, HelpCircle, Calendar, RefreshCw, CheckCircle2, Moon, Smartphone, Mic, MicOff } from 'lucide-react-native';
import { Avatar, Brand, Button, IconBadge, Plant, Sheet, Tag, Notice, Traffic, TriageCircle } from './src/components';
import { ProfileForm, RecordForm, Login } from './src/forms';
import { Paywall } from './src/Paywall';
import { FamilyTree } from './src/FamilyTree';
import { AppData, Chat, Light, Profile, RecordItem, Reply, Triage } from './src/types';
import { demoData, emptyData, disclaimer, relativeTime, uid } from './src/data';
import { ancestorFlags, createsCycle, profileLimit } from './src/policy.mjs';
import { demoReply } from './src/demo';
import { isLive, warmCareBackend, liveReply, loadAccount, request, saveProfile, saveRecord, supabase } from './src/api';
import { conversationLanguage, detectLanguage, pick, voiceCopy } from './src/language.mjs';
import { withoutMember } from './src/family.mjs';
import { removeProfile } from './src/api';
